<?php use kartik\select2\Select2;use yii\helpers\Html;use yii\widgets\ActiveForm;$this->title='Laporan Jadwal Mingguan';?>
<h1><?=$this->title?></h1><div class="card card-success card-outline"><div class="card-body"><?php $form=ActiveForm::begin(['method'=>'get','action'=>['index']])?><div class="row align-items-center border-bottom py-2"><div class="col-md-3 text-primary font-weight-bold">Periode Akademik</div><div class="col-md-9"><?=$form->field($model,'academic_period',['template'=>'{input}{error}'])->dropDownList($periods)?></div></div><div class="row align-items-center border-bottom py-2"><div class="col-md-3 text-primary font-weight-bold">Prodi</div><div class="col-md-9"><?=$form->field($model,'study_program_id',['template'=>'{input}{error}'])->widget(Select2::class,['data'=>$studyPrograms,'options'=>['placeholder'=>'Pilih Program Studi']])?></div></div><div class="row align-items-center border-bottom py-2"><div class="col-md-3 text-primary font-weight-bold">Semester</div><div class="col-md-9"><?=$form->field($model,'semester',['template'=>'{input}{error}'])->dropDownList($semesters)?></div></div><div class="row align-items-center border-bottom py-2"><div class="col-md-3 text-primary font-weight-bold">Mahasiswa</div><div class="col-md-9"><?=$form->field($model,'student_id',['template'=>'{input}{error}'])->widget(Select2::class,['data'=>$students,'options'=>['placeholder'=>'Semua mahasiswa'],'pluginOptions'=>['allowClear'=>true]])?></div></div><div class="row align-items-center border-bottom py-2"><div class="col-md-3 text-primary font-weight-bold">Format</div><div class="col-md-9"><?=$form->field($model,'format',['template'=>'{input}{error}'])->dropDownList(['html'=>'HTML','pdf'=>'PDF'])?></div></div><div class="row align-items-center border-bottom py-2"><div class="col-md-3 text-primary font-weight-bold">KOP</div><div class="col-md-9"><?=$form->field($model,'use_letterhead',['template'=>'{input}{error}'])->checkbox(['label'=>'Gunakan KOP'])?></div></div><div class="text-right mt-3"><?=Html::submitButton('<i class="fas fa-search"></i> Tampilkan',['class'=>'btn btn-primary'])?> <?=Html::button('<i class="fas fa-external-link-alt"></i> Lihat di Tab Baru',['class'=>'btn btn-primary','id'=>'open-report'])?></div><?php ActiveForm::end()?></div></div>
